"mandate @ 0.3

module acme.tasks.land @ 0.1

use acme.system.{CoreApi, TokenIssuance, auth, core, mcp}
use std.{component, git}

capability Repos = component.repo(auth, mcp, core)

type Change = { files: List<Text> }

type Plan = { summary: Text }

contract ChangeAccepted(change: Change) {
  accept listed "The change names its files"
    by static len(change.files) >= 1
}

contract PlanAccepted(plan: Plan) {
  accept summarized "The plan says what changes"
    by static len(plan.summary) >= 1
}

workflow Land(task: Text) -> Text
  caps    Repos
{
  let plan = verify Plan { summary: task } against PlanAccepted(Plan { summary: task })
  let a = verify Change { files: ["src/token.ts"] } against ChangeAccepted(Change { files: ["src/token.ts"] })
  let c = verify Change { files: ["src/main/java/Api.java"] } against ChangeAccepted(Change { files: ["src/main/java/Api.java"] })
  let m = verify Change { files: ["src/tools.ts"] } against ChangeAccepted(Change { files: ["src/tools.ts"] })
  let landed = changeset(plan) {
    member auth = git.merge(a)
    member core = git.merge(c)
    member mcp = git.merge(m)
    order auth, core, mcp
    change TokenIssuance additive
    change CoreApi additive
    approve role "architect"
  } idempotent_by task
  "landed"
}
"

"mandate @ 0.4

module company.migrations @ 0.1

use company.domain.{Repo, Summary}
use std.{exec, fs, git, human, model}

role platform_lead "Platform lead"

role release_manager "Release manager"

capability Build = exec(commands: ["npm"], args_prefix: [["ci"], ["test"]])

capability Merge = git.pr("company/backend", "company/frontend")

capability ModelStd = model.infer(tier: standard)

capability RepoRead = fs.read("/work/repos")

capability SrcWrite = fs.write("/work/repos")

contract Moved(repo: Repo, s: Summary) {
  accept moved "The migrator reports what it moved"
    by static len(s.migrated) >= 1
  accept nothing_left "Nothing of the repository is left to move"
    by static len(s.left) == 0
  accept release_approved "The release manager accepts the change"
    by human.approve(role: release_manager)
}

agent Lead {
  role   "Plans what is left after the bulk migration and writes sub-programs for it."
  caps   ModelStd, RepoRead
  budget { tokens: 2M, spend: 10 USD, steps: 40 }
  skill finish(repos: List<Repo>, done: List<Outcome<Inferred<Summary>>>) -> Inferred<Summary> ! {Fs.Read, Model}
}

agent Migrator {
  role   "Moves one repository to the new logging API."
  caps   Build, ModelStd, RepoRead, SrcWrite
  budget { tokens: 400k, time: 20m, spend: 0.5 USD, steps: 12 }
  skill migrate(repo: Repo) -> Inferred<Summary> ! {Exec, Fs.Read, Fs.Write, Model}
}

workflow MigrateAll(repos: List<Repo>) -> Inferred<Summary>
  envelope {
    owner   platform_lead
    caps    Build, Merge, ModelStd, RepoRead, SrcWrite
    budget  { tokens: 80M, time: 6h, spend: 120 USD, steps: 2000, agents: 200 }
    spawn   { max_concurrent: 16, max_class: internal }
    approve git.merge by release_manager
  }
{
  let done = map repo in repos max 150 par 16 with caps SrcWrite.narrow(repo.root) {
    delegate Migrator.migrate(repo)
  }
  plan Lead.finish(repos, done) within envelope
}
"
